  const list=dialog.querySelector('.tracker-contact-list');const draw=query=>{list.innerHTML=this.catalog.remoteContacts.filter(c=>(c.display_name||c.profile?.display_name||c.login||c.profile?.login||c.actor_id).toLocaleLowerCase().includes(query.toLocaleLowerCase())).map(c=>`<button type="button" class="tracker-contact" data-contact="${attr(c.peer_id+':'+c.actor_id)}">${icon('network')}${esc(c.display_name||c.profile?.display_name||c.login||c.profile?.login||c.actor_id)}</button>`).join('');};draw('');dialog.querySelector('input').oninput=e=>draw(e.target.value);
